def count_equal_arc_abc_choices():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    difficulties = list(map(int, data[1:N+1]))

    difficulties.sort()

    count = 0
    half = N // 2

    # Iterate over possible K values to find equal divisions
    for i in range(N + 1):
        if i < half:
            # If we are choosing the first i elements for ARCs, we need the remaining N-i elements for ABCs
            if difficulties[i] > difficulties[N - half - 1]:
                count += 1
        elif i > half:
            # If we are choosing the last i elements for ARCs, we need the remaining N-i elements for ABCs
            if difficulties[i - 1] < difficulties[half - 1]:
                count += 1
        else:
            # Exact median split, all elements are equally distributed
            count += 1

    print(count)
